class ChatGptText {
  const ChatGptText._(this._v);
  final Map<String, String> _v;

  /// A label by its source key (for keys that come from server values); null if unknown.
  String? operator [](String key) => _v[key];

  /// Every source key, in source order.
  Iterable<String> get keys => _v.keys;

  String get name => _v['name']!;
  String get title => _v['title']!;
  String get plan => _v['plan']!;
  String get stepSignIn => _v['stepSignIn']!;
  String get stepPaste => _v['stepPaste']!;
  String get hint => _v['hint']!;
  String get continue_ => _v['continue']!;
  String get address => _v['address']!;
  String get connect => _v['connect']!;
  String get continuingAs => _v['continuingAs']!;
  String get otherAccount => _v['otherAccount']!;
  String get connected => _v['connected']!;
  String get connectedNoAccount => _v['connectedNoAccount']!;
  String get usingPlan => _v['usingPlan']!;
  String get planNotUsed => _v['planNotUsed']!;
  String get manageUsage => _v['manageUsage']!;
  String get signOut => _v['signOut']!;
  String get signedOut => _v['signedOut']!;
  String get revocationUnconfirmed => _v['revocationUnconfirmed']!;
  String get signInAgain => _v['signInAgain']!;
  String get planLimitTitle => _v['planLimitTitle']!;
  String get planLimitLine => _v['planLimitLine']!;
}

